import{_ as e,C as r,o,c as l,a2 as a,E as s}from"./chunks/framework.kOe0DhAP.js";const T=JSON.parse('{"title":"核心设计","description":"把资产、订单和订单簿作为相互关联的独立对象。","frontmatter":{"title":"核心设计","description":"把资产、订单和订单簿作为相互关联的独立对象。"},"headers":[],"relativePath":"06/0604/060004.md","filePath":"06/0604/060004.md"}'),i={name:"06/0604/060004.md"};function n(h,t,p,c,_,b){const d=r("Flow");return o(),l("div",null,[t[0]||(t[0]=a('<div class="doc-eyebrow">现货手册 / TGEX KNOWLEDGE BASE</div><h1 id="核心设计" tabindex="-1">核心设计 <a class="header-anchor" href="#核心设计" aria-label="Permalink to &quot;核心设计&quot;">​</a></h1><div class="doc-lead">把资产、订单和订单簿作为相互关联的独立对象。</div><h2 id="account" tabindex="-1">账户与资产 <a class="header-anchor" href="#account" aria-label="Permalink to &quot;账户与资产 {#account}&quot;">​</a></h2><p>买单占用计价币，卖单占用基础币。冻结金额不能只依赖客户端计算，应由服务端结合价格、数量和费用规则确定。未成交资金在订单终止后释放。可用与冻结的口径见<a href="/05/0501/050001#balances">资产体系与余额设计</a>。</p><p>教学演算中的占用可先按下列方式理解（真实公式以产品规则为准）：</p><table tabindex="0"><thead><tr><th>方向</th><th>占用什么</th><th>简化估算</th></tr></thead><tbody><tr><td>限价买入</td><td>计价币</td><td>约 <code>限价 × 数量</code>，若费用从计价币扣则再加费用缓冲</td></tr><tr><td>限价卖出</td><td>基础币</td><td>约等于委托数量</td></tr><tr><td>市价买入</td><td>计价币</td><td>通常按提交金额或按估价占用，版本差异需核对</td></tr><tr><td>市价卖出</td><td>基础币</td><td>约等于委托数量</td></tr></tbody></table><p>贯穿示例中，用户以 60,000 限价买入 0.01 BTC、先忽略费用时，预占 600 USDT。部分成交 0.006 BTC 后，已支出 360，剩余占用应降到约 240；撤销剩余后再把 240 解冻回可用。</p><h2 id="states" tabindex="-1">订单与状态流转 <a class="header-anchor" href="#states" aria-label="Permalink to &quot;订单与状态流转 {#states}&quot;">​</a></h2>',9)),s(d,{steps:["未成交","部分成交","完全成交 / 已撤销"]}),t[1]||(t[1]=a('<p>这是一条示意路径。未成交也可以直接完全成交或撤销；部分成交后继续成交或撤销。工程状态枚举对应未成交、部分成交、完全成交、已撤销，具体存储值不必暴露给业务读者。</p><p>阅读订单时建议区分三类数量：</p><table tabindex="0"><thead><tr><th>数量概念</th><th>含义</th></tr></thead><tbody><tr><td>原始数量</td><td>用户最初提交的买卖量</td></tr><tr><td>已成交数量</td><td>累计成交，只增不减</td></tr><tr><td>剩余数量</td><td>尚未成交、仍可能挂在簿上或等待终止的部分</td></tr></tbody></table><p>撤单只作用于剩余数量，不能把已成交量改回零。一个委托可以关联多笔成交记录；每笔成交都应能回溯到双方订单、价格、数量与唯一标识。</p><h2 id="orderbook" tabindex="-1">订单簿与撮合机制 <a class="header-anchor" href="#orderbook" aria-label="Permalink to &quot;订单簿与撮合机制 {#orderbook}&quot;">​</a></h2><p>已检查实现中，买方价格队列降序，卖方价格队列升序，撮合优先寻找最优对手价格。买单价格达到卖方价格时可以成交。</p><p>订单簿反映尚未成交的意图，不等于成交历史，也不等于用户的全部历史委托。深度展示通常是把同价位未成交量聚合后的结果，见<a href="/06/0606/060006">行情与推送</a>。</p><p>以下细节在文档中不固化，需结合具体撮合路径确认后再写入业务说明：</p><ul><li>相同价位的排队规则（例如是否严格时间优先）</li><li>外部成交分支如何写入本地订单与账务</li></ul><p>把「最优价优先」写成业务约束是安全的；把未经核对的同价排队或外部成交语义写成事实，则会误导读者。</p>',10))])}const m=e(i,[["render",n]]);export{T as __pageData,m as default};
